function firstPdfUrl(data: unknown): string | null {
  const payload = unwrapData<{ pdfUrl?: string | null; contents?: Array<{ pdfUrl?: string | null }> }>(data);
  return payload?.pdfUrl ?? payload?.contents?.find((c) => c.pdfUrl)?.pdfUrl ?? null;
}

